using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using MovieApi.Data; using MovieApi.Models; using MovieApi.DTOs;
namespace MovieApi.Controllers;
[ApiController,Route("api/movies")]
public class MoviesController(MovieContext db):ControllerBase {
[HttpGet] public async Task<IActionResult> Get(string? genre=null,int? year=null,string? actor=null){ var q=db.Movies.AsQueryable(); if(genre!=null) q=q.Where(m=>m.Genre==genre || m.MovieGenres.Any(g=>g.Genre.Name==genre)); if(year!=null) q=q.Where(m=>m.Year==year); if(actor!=null) q=q.Where(m=>m.MovieActors.Any(a=>a.Actor.Name.Contains(actor))); return Ok(await q.Select(m=>new MovieDto(m.Id,m.Title,m.Year,m.Genre,m.Duration)).ToListAsync()); }
[HttpGet("{id:int}")] public async Task<IActionResult> GetOne(int id,bool withactors=false){if(withactors)return await Details(id); var m=await db.Movies.FindAsync(id); return m==null?NotFound():Ok(new MovieDto(m.Id,m.Title,m.Year,m.Genre,m.Duration));}
[HttpGet("{id:int}/details")] public async Task<IActionResult> Details(int id){var m=await db.Movies.Where(m=>m.Id==id).Select(m=>new MovieDetailDto(m.Id,m.Title,m.Year,m.Genre,m.Duration,m.Details==null?null:new DetailsDto{Synopsis=m.Details.Synopsis,Language=m.Details.Language,Budget=m.Details.Budget},m.Reviews.Select(r=>new ReviewDto(r.Id,r.ReviewerName,r.Comment,r.Rating)).ToList(),m.MovieActors.Select(a=>new ActorDto(a.ActorId,a.Actor.Name,a.Actor.BirthYear,a.Role)).ToList(),m.Director==null?null:m.Director.Name,m.Country==null?null:m.Country.Name,m.MovieGenres.Select(g=>g.Genre.Name).ToList())).FirstOrDefaultAsync();return m==null?NotFound():Ok(m);}
private async Task<bool> Valid(MovieCreateDto d)=> (d.DirectorId==null||await db.Directors.AnyAsync(x=>x.Id==d.DirectorId))&&(d.CountryId==null||await db.Countries.AnyAsync(x=>x.Id==d.CountryId))&&await db.Genres.CountAsync(x=>d.GenreIds.Contains(x.Id))==d.GenreIds.Distinct().Count();
private void Apply(Movie m,MovieCreateDto d){m.Title=d.Title;m.Year=d.Year;m.Genre=d.Genre;m.Duration=d.Duration;m.DirectorId=d.DirectorId;m.CountryId=d.CountryId; if(d.Details!=null){m.Details??=new();m.Details.Synopsis=d.Details.Synopsis;m.Details.Language=d.Details.Language;m.Details.Budget=d.Details.Budget;}else m.Details=null; m.MovieGenres.RemoveAll(x=>!d.GenreIds.Contains(x.GenreId));foreach(var g in d.GenreIds.Distinct().Where(g=>!m.MovieGenres.Any(x=>x.GenreId==g)))m.MovieGenres.Add(new(){GenreId=g});}
[HttpPost] public async Task<IActionResult> Post(MovieCreateDto d){if(!await Valid(d))return BadRequest("Invalid reference ID");var m=new Movie();Apply(m,d);db.Movies.Add(m);await db.SaveChangesAsync();return CreatedAtAction(nameof(GetOne),new{id=m.Id},new MovieDto(m.Id,m.Title,m.Year,m.Genre,m.Duration));}
[HttpPut("{id:int}")] public async Task<IActionResult> Put(int id,MovieUpdateDto d){var m=await db.Movies.Include(x=>x.Details).Include(x=>x.MovieGenres).FirstOrDefaultAsync(x=>x.Id==id);if(m==null)return NotFound();if(!await Valid(d))return BadRequest("Invalid reference ID");Apply(m,d);await db.SaveChangesAsync();return NoContent();}
[HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var m=await db.Movies.FindAsync(id);if(m==null)return NotFound();db.Remove(m);await db.SaveChangesAsync();return NoContent();}
}
